(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.32)*12;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025+t*0.15)*8 + Math.cos(my*0.03-t*0.4)*6;
  const w2y = Math.cos(my*0.028-t*0.35)*8 + Math.sin(mx*0.022+t*0.45)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.075, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.095, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.085, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.1, 2.1, 0.85],
    [400+Math.cos(t*0.38+1)*60, 220+Math.sin(t*0.72+4)*40, 0.07, 2.4, 1.05]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+1.5)*w;
    cS+=Math.sin(d*f*1.4-t*sp*0.8+3.0)*w*0.5;
  }
  const wSum=src.reduce((s,v)=>s+v[4],0);
  const act=aS/wSum, inh=iS/wSum, cross=cS/wSum;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.75)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2
    +Math.sin((sx+sy)*0.11+t*2.3)*0.15+Math.sin((sx-sy)*0.09-t*1.8)*0.15
    +Math.sin(sx*0.06+t*1.5)*Math.sin(sy*0.05-t*1.2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.045-ang*3.5-t*1.4)+Math.sin(dist*0.035+ang*4.5-t*1.1))*0.35;
  const sp2=Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const micro=Math.sin(sx*0.3+Math.sin(sy*0.25+t)*2)*Math.sin(sy*0.3+Math.sin(sx*0.2-t)*2)*0.12;
  const react1=Math.tanh((act-inh*0.65+bg*0.25+sp1)*2.0);
  const react2=Math.tanh((cross-inh*0.5+sp2+micro)*1.8);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4+Math.sin(sx*0.08-t*0.5)*Math.cos(sy*0.1+t*0.3)*0.3)*1.6)*0.25;
  const combined=react1*0.55+react2*0.2+cell*0.25;
  const v=combined*0.5+0.5;
  const pal=[
    [5,12,45],[10,35,80],[15,70,105],[20,120,130],[45,165,140],
    [120,190,120],[190,200,85],[220,175,60],[230,130,55],[215,85,65],
    [185,50,75],[130,30,80],[75,20,65],[30,15,50],[5,12,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(react1*Math.PI)*0.18;
  const edge=Math.abs(react1)>0.65?1.12:1.0;
  const glow=Math.max(0,react1-0.3)*0.3;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*80))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*50))|0
  ];
}
